"""Diccionario inicial de variables de las fuentes Bellabeat/Fitbit."""
import pandas as pd

DESCRIPTIONS={"Id":"Identificador anonimizado del participante; solo metadato.","Date":"Fecha normalizada de observación persona-día.","TotalSteps":"Conteo total de pasos del día (pasos).","TotalDistance":"Distancia total registrada (millas en el origen).","TrackerDistance":"Distancia por rastreador (millas).","LoggedActivitiesDistance":"Distancia de actividad registrada manualmente (millas).","VeryActiveDistance":"Distancia de actividad muy intensa (millas).","ModeratelyActiveDistance":"Distancia de actividad moderada (millas).","LightActiveDistance":"Distancia de actividad ligera (millas).","SedentaryActiveDistance":"Distancia en estado sedentario (millas).","VeryActiveMinutes":"Minutos de actividad muy intensa.","FairlyActiveMinutes":"Minutos de actividad moderada.","LightlyActiveMinutes":"Minutos de actividad ligera.","SedentaryMinutes":"Minutos sedentarios.","Calories":"Calorías estimadas por el dispositivo; no medida clínica.","TotalSleepRecords":"Número de registros de sueño de la fecha.","TotalMinutesAsleep":"Minutos estimados dormidos.","TotalTimeInBed":"Minutos en cama registrados."}
def dictionary_frame(): return pd.DataFrame([{"variable":k,"descripción":v,"uso":("metadato" if k in {"Id","Date"} else "candidata numérica") } for k,v in DESCRIPTIONS.items()])

